#!/usr/bin/env bash
# Run one remediation batch on a single Actions worker. Docker images remain in
# that worker's daemon and are reused by every repository in this batch.
set -euo pipefail

OPENHANDS_IMAGE="ghcr.io/all-hands-ai/openhands@sha256:00968de77a7b36546413e1f3b5c6b4e2c387d19ade54de7926e10f5b3d265fa6"
RUNTIME_IMAGE="ghcr.io/all-hands-ai/runtime:0.59-nikolaik"
HOST_WORKSPACE="$GITHUB_WORKSPACE"
BATCH=${REMEDIATION_BATCH:?REMEDIATION_BATCH must contain a JSON array}
WORKTREES_DIR="$GITHUB_WORKSPACE/remediation-worktrees"
mkdir -p "$WORKTREES_DIR"
gh auth setup-git

run_repo() {
  local repo=$1 issue_num=$2 target=$3 branch issue_state
  branch="health/fix-issue-$issue_num"
  issue_state=$(gh issue view "$issue_num" --repo "$repo" --json state --jq .state) || return 1
  if [[ $issue_state != OPEN ]]; then
    echo "Issue #$issue_num on $repo closed before remediation; skipping."
    return 0
  fi

  git -C "$target" checkout -b "$branch" || return 1
  gh issue view "$issue_num" --repo "$repo" --json body --jq .body >"$target/.issue-context.md" || return 1
  mkdir -p "$HOME/.openhands"

  docker run --rm \
    -e LLM_API_KEY="$GEMINI_API_KEY" \
    -e LLM_MODEL="gemini/gemini-3.7-flash" \
    -e SANDBOX_USER_ID="$(id -u)" \
    -e SANDBOX_VOLUMES="$HOST_WORKSPACE$target:/workspace:rw" \
    -e SANDBOX_RUNTIME_CONTAINER_IMAGE="$RUNTIME_IMAGE" \
    -v /var/run/docker.sock:/var/run/docker.sock \
    -v "$HOME/.openhands:/.openhands" \
    -v "$HOST_WORKSPACE$target:/workspace" \
    --add-host host.docker.internal:host-gateway \
    "$OPENHANDS_IMAGE" \
    python -m openhands.core.main \
      -t "Read .issue-context.md and address all technical vulnerabilities, CodeQL warnings, dependency updates, and GitHub Actions workflow issues mentioned. If workflows are flagged, update action versions in .github/workflows/*.yml to the latest releases. Do not hand-edit .github/workflows/actions.lock: the pipeline regenerates it with 'gh actions-lock' after your edits. If the repo has no lockfile, use full 40-character commit SHAs for any action reference you add or change. If .issue-context.md indicates the repo is an Archival Candidate, ignore routine package updates. Run native test suites ('sbt test', 'npm test', 'pytest', or 'shellcheck *.sh') to verify cleanly." || return 1

  rm -f "$target/.issue-context.md"
  if [[ -f "$target/.github/workflows/actions.lock" ]] && \
    git -C "$target" status --porcelain -- .github/workflows | grep -qE '\.ya?ml$'; then
    echo "Regenerating .github/workflows/actions.lock for $repo..."
    if ! gh extension list | grep -q 'github/gh-actions-lock'; then
      gh extension install github/gh-actions-lock >/dev/null 2>&1 ||
        echo "::warning::Could not install gh-actions-lock for $repo"
    fi
    (cd "$target" && gh actions-lock) ||
      echo "::warning::gh actions-lock failed for $repo; the lockfile may be stale"
  fi

  if [[ -n $(git -C "$target" status --porcelain) ]]; then
    git -C "$target" config user.name "github-actions[bot]"
    git -C "$target" config user.email "github-actions[bot]@users.noreply.github.com"
    git -C "$target" add -A
    git -C "$target" commit -m "fix(health): automated OpenHands resolution for issue #$issue_num" || return 1
    git -C "$target" push origin "$branch" || return 1

    gh pr create \
      --repo "$repo" \
      --head "$branch" \
      --title "🤖 [PR] Resolve Health Issue #$issue_num" \
      --body "### Automated Maintenance Fixes
Generated by OpenHands using **Gemini 3.7 Flash**.

**Closes #$issue_num**

**Verification Status:**
- [x] Examined requirements from Issue #$issue_num
- [x] Audited and updated GitHub Actions workflows
- [x] Applied safe dependency and code vulnerability patches
- [x] Verified native build and unit test execution

Please inspect the diff and approve." \
      --draft || return 1
  else
    echo "OpenHands completed without generating code diffs for issue #$issue_num on $repo."
  fi
}

# Issues were checked in the preflight job. Recheck branch/issue state before
# cloning, then let clones use GitHub CLI's authenticated remote URL.
READY_REPOS=()
READY_ISSUES=()
FAILURES=0
while IFS= read -r item; do
  repo=$(jq -r '.repo' <<<"$item")
  issue_num=$(jq -r '.issue' <<<"$item")
  target="$WORKTREES_DIR/${repo//\//__}"
  branch="health/fix-issue-$issue_num"
  echo "Checking $repo (issue #$issue_num)..."
  state=$(gh issue view "$issue_num" --repo "$repo" --json state --jq .state) || {
    echo "::error::Could not recheck issue #$issue_num on $repo"
    FAILURES=$((FAILURES + 1))
    continue
  }
  if [[ $state != OPEN ]]; then
    echo "Issue #$issue_num on $repo is no longer open; skipping."
    continue
  fi
  output=$(git ls-remote --heads "https://github.com/$repo.git" "$branch") || {
    echo "::error::Could not check branch state for $repo"
    FAILURES=$((FAILURES + 1))
    continue
  }
  if [[ -n $output ]]; then
    echo "Branch $branch already exists on $repo; skipping."
    continue
  fi
  if ! gh repo clone "$repo" "$target" -- --depth=1; then
    echo "::error::Could not clone $repo"
    FAILURES=$((FAILURES + 1))
    continue
  fi
  output=$(git -C "$target" ls-remote --heads origin "$branch") || {
    echo "::error::Could not recheck branch state for $repo"
    FAILURES=$((FAILURES + 1))
    continue
  }
  if [[ -n $output ]]; then
    echo "Branch $branch appeared on $repo during checkout; skipping."
    continue
  fi
  READY_REPOS+=("$repo")
  READY_ISSUES+=("$issue_num")
done < <(jq -c '.[]' <<<"$BATCH")

if ((${#READY_REPOS[@]} > 0)); then
  docker pull "$OPENHANDS_IMAGE"
  docker pull "$RUNTIME_IMAGE"
  for i in "${!READY_REPOS[@]}"; do
    repo=${READY_REPOS[$i]}
    issue_num=${READY_ISSUES[$i]}
    target="$WORKTREES_DIR/${repo//\//__}"
    echo "Running OpenHands for $repo (issue #$issue_num)..."
    if run_repo "$repo" "$issue_num" "$target"; then
      :
    else
      echo "::error::OpenHands remediation failed for $repo (issue #$issue_num)"
      FAILURES=$((FAILURES + 1))
    fi
  done
fi

((FAILURES == 0)) || exit 1
